import json,urllib.parse,urllib.request,re,concurrent.futures
q='(single-cell OR scRNA OR \"single cell RNA\") AND (mouse OR murine) AND (brain OR neural OR neuron OR spinal OR retina OR cortex) AND FIRST_PDATE:[2015-01-01 TO 2023-12-31]'
u='https://www.ebi.ac.uk/europepmc/webservices/rest/search?'+urllib.parse.urlencode({'query':q,'resultType':'lite','pageSize':1000,'format':'json','sort':'CITED desc'})
d=json.load(urllib.request.urlopen(u,timeout=60)); res=d.get('resultList',{}).get('result',[])
print('n',len(res),d.get('hitCount'))
sel=[]
for x in res:
 t=re.sub('<["'^>]+>'"',' ',x.get('title',''))
 if x.get('pmcid') and re.search(r'(brain|neural|neuron|spinal|retina|cortex|hypothalam|cerebell|development|glia|olfactory|ganglion)',t,re.I): sel.append((x['pmcid'],t,x.get('firstPublicationDate','')))
print('sel',len(sel))

def get(z):
 pmc,t,date=z
 try:
  s=urllib.request.urlopen(f'https://www.ebi.ac.uk/europepmc/webservices/rest/{pmc}/fullTextXML',timeout=25).read().decode('utf8','ignore')
  return pmc,date,t,sorted(set(re.findall(r'GSE\\d+',s)))
 except Exception as e: return pmc,date,t,[]
with concurrent.futures.ThreadPoolExecutor(max_workers=16) as ex:
 for pmc,date,t,acc in ex.map(get,sel):
  if acc: print(pmc,date,'|',t[:160],'|',','.join(acc))
PY"

